/* ---------- Portugal (2/2), France régionale ---------- */
const D39 = [
{ id:'arroz-doce', c:'eu', lat:40.661, lon:-7.910, base:6, prep:15, cook:45, diff:1, tags:['sweet','comfort','rice'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'rice',food:['#f4f0e6','#f0e0bc','#8f3b2a','#e8dcc0'],garnish:'#c9754a'},
  n:{fr:'Arroz doce',en:'Arroz doce'},
  p:{fr:'Viseu, Beira Alta, Portugal',en:'Viseu, Beira Alta, Portugal'},
  d:{fr:"Le riz au lait portugais, jaune de jaunes d'œufs, servi froid en plats larges et décoré de cannelle au pochoir. Il n'y a pas de fête de village au Portugal sans une table entière couverte de ces plats.",
     en:"The Portuguese rice pudding, yellow with egg yolks, served cold in wide dishes and stencilled with cinnamon. There is no village festa in Portugal without a whole table covered in these dishes."},
  i:[['long_grain_rice',250,'g'],['whole_milk',1.2,'l'],['sugar',250,'g'],['egg_yolk',6,'pc'],['lemon_zest',2,'pc'],['cinnamon',3,'pc'],['butter',30,'g'],['salt',null,'']],
  s:{fr:["Faites cuire le riz 10 minutes dans une eau salée avec un bâton de cannelle et le zeste, puis égouttez sans rincer.","Portez le lait à frémissement avec le reste de cannelle et de zeste, versez-y le riz et laissez cuire 30 minutes à feu doux, en remuant souvent.","Ajoutez le sucre seulement à ce moment : plus tôt, il durcirait le grain.","Hors du feu, incorporez les jaunes battus avec un peu de riz chaud, puis remettez deux minutes sur feu très doux sans bouillir.","Versez dans des plats larges, laissez refroidir et dessinez à la cannelle moulue à travers un pochoir de papier."],
     en:["Cook the rice for 10 minutes in salted water with a cinnamon stick and the zest, then drain without rinsing.","Bring the milk to a simmer with the remaining cinnamon and zest, tip in the rice and cook for 30 minutes over low heat, stirring often.","Add the sugar only at this point: any earlier and it would toughen the grain.","Off the heat, stir in the yolks beaten with a little hot rice, then return to very low heat for two minutes without boiling.","Pour into wide dishes, cool, and stencil a pattern with ground cinnamon through cut paper."]} },

{ id:'pastel-de-tentugal', c:'eu', lat:40.243, lon:-8.582, base:10, prep:120, cook:20, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f2dfa8','#e0b45a','#f4f0e6','#c98a2c'],garnish:'#c9754a'},
  n:{fr:'Pastel de Tentúgal',en:'Pastel de Tentúgal'},
  p:{fr:'Tentúgal, Beira Litoral, Portugal',en:'Tentúgal, Beira Litoral, Portugal'},
  d:{fr:"Une pâte étirée si finement qu'on lit à travers, enroulée sur une crème d'œufs. Les carmélites de Tentúgal en gardaient le secret ; la pâte se travaille encore dans des pièces sans courant d'air, aux fenêtres closes.",
     en:"A pastry stretched so thin you can read through it, rolled around an egg cream. The Carmelite nuns of Tentúgal kept the secret; the dough is still worked in rooms without a draught, windows shut."},
  i:[['flour',400,'g'],['warm_water',200,'ml'],['egg_yolk',12,'pc'],['sugar',400,'g'],['water',200,'ml'],['lemon_zest',1,'pc'],['cinnamon',1,'tsp'],['butter',100,'g'],['powdered_sugar',60,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, l'eau tiède et le sel 25 minutes : la pâte doit devenir lisse et souple comme du cuir fin.","Laissez-la reposer 2 heures sous un bol, puis étirez-la à la main sur une grande nappe farinée, jusqu'à voir le tissu au travers.","Préparez la crème : cuisez le sucre et l'eau au petit boulé, laissez tiédir et incorporez les jaunes hors du feu, puis épaississez à feu doux.","Découpez des bandes de pâte, badigeonnez de beurre fondu, déposez la crème en boudin et roulez sans serrer.","Repliez les extrémités, enfournez 15 minutes à 220 °C et poudrez de sucre glace et de cannelle."],
     en:["Knead the flour, warm water and salt for 25 minutes: the dough must become smooth and supple as fine leather.","Rest it for 2 hours under a bowl, then stretch it by hand over a large floured cloth until you can see the weave through it.","Make the cream: cook the sugar and water to soft ball, cool a little, stir in the yolks off the heat, then thicken over low heat.","Cut strips of pastry, brush with melted butter, pipe the cream along them and roll loosely.","Fold in the ends, bake for 15 minutes at 220°C and dust with icing sugar and cinnamon."]} },

{ id:'carne-de-porco-a-alentejana', c:'eu', lat:38.372, lon:-8.512, base:4, prep:30, cook:40, diff:2, tags:['pork','sea','sunday'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#e0913a','#f0e8d0','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Porc à l’alentejana',en:'Carne de porco à alentejana'},
  p:{fr:'Alcácer do Sal, Alentejo, Portugal',en:'Alcácer do Sal, Alentejo, Portugal'},
  d:{fr:"Du porc mariné à la pâte de poivron rouge, sauté avec des palourdes et des pommes de terre frites. L'alliance terre-mer paraît étrange jusqu'à ce qu'on sache que le porc alentejan paissait au bord des estuaires.",
     en:"Pork marinated in red pepper paste, sautéed with clams and fried potatoes. The surf-and-turf pairing seems odd until you learn that Alentejo pigs grazed along the estuaries."},
  i:[['pork_loin',700,'g'],['clams',1,'kg'],['massa_de_pimentao',3,'tbsp'],['white_wine',200,'ml'],['garlic',6,'clove'],['bay_leaf',2,'pc'],['potato',700,'g'],['cilantro',1,'bunch'],['lemon',1,'pc'],['pickles',60,'g'],['olive_oil',100,'ml'],['frying_oil',500,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le porc en cubes de 3 cm et laissez-le mariner 12 heures dans la pâte de poivron, le vin blanc, l'ail écrasé et le laurier.","Faites dégorger les palourdes 2 heures dans de l'eau salée pour qu'elles rendent leur sable.","Égouttez et épongez la viande, puis saisissez-la à feu vif dans l'huile d'olive, par petites quantités.","Versez la marinade filtrée, laissez réduire de moitié, puis ajoutez les palourdes et couvrez : elles s'ouvrent en 4 minutes.","Faites frire les pommes de terre en cubes, mêlez-les au plat, couvrez de coriandre ciselée et servez avec citron et cornichons."],
     en:["Cut the pork into 3 cm cubes and marinate for 12 hours in the pepper paste, white wine, crushed garlic and bay.","Purge the clams for 2 hours in salted water so they release their sand.","Drain and dry the meat, then sear it over high heat in olive oil, in small batches.","Pour in the strained marinade, reduce by half, then add the clams and cover: they open in 4 minutes.","Deep-fry the diced potatoes, fold them through, cover with chopped coriander and serve with lemon and gherkins."]} },

{ id:'arroz-de-lampreia', c:'eu', lat:42.078, lon:-8.482, base:6, prep:45, cook:60, diff:3, tags:['sea','rice','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'rice',food:['#6f2a2a','#8f3b2a','#e8dcb8','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Riz de lamproie',en:'Lamprey rice'},
  p:{fr:'Monção, Minho, Portugal',en:'Monção, Minho, Portugal'},
  d:{fr:"La lamproie du Minho, pêchée de janvier à avril, mijotée dans son propre sang et le vin d'Alvarinho. Un poisson préhistorique sans mâchoire, dont le goût tient plus du gibier que de la mer.",
     en:"The Minho lamprey, fished from January to April, stewed in its own blood and Alvarinho wine. A prehistoric jawless fish whose taste is closer to game than to the sea."},
  i:[['lamprey',1.5,'kg'],['long_grain_rice',400,'g'],['white_wine',500,'ml'],['onion',3,'pc'],['garlic',6,'clove'],['ripe_tomato',300,'g'],['bay_leaf',3,'pc'],['cloves',4,'pc'],['olive_oil',100,'ml'],['white_vinegar',3,'tbsp'],['parsley',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Ébouillantez la lamproie pour retirer le mucus, puis recueillez le sang dans un bol contenant le vinaigre.","Tronçonnez-la en morceaux de 4 cm et laissez-la mariner 3 heures dans le vin blanc avec le laurier et les clous.","Faites fondre l'oignon et l'ail dans l'huile, ajoutez la tomate râpée et laissez compoter.","Versez la marinade, portez à frémissement et pochez les tronçons 25 minutes ; retirez-les et gardez-les au chaud.","Cuisez le riz 15 minutes dans ce bouillon, puis liez au sang hors du feu, sans bouillir. Remettez le poisson et servez aussitôt."],
     en:["Scald the lamprey to remove the mucus, then collect the blood in a bowl holding the vinegar.","Cut it into 4 cm sections and marinate for 3 hours in the white wine with the bay and cloves.","Soften the onion and garlic in the oil, add the grated tomato and let it cook down.","Pour in the marinade, bring to a simmer and poach the sections for 25 minutes; lift them out and keep warm.","Cook the rice for 15 minutes in that broth, then bind with the blood off the heat, without boiling. Return the fish and serve at once."]} },

{ id:'maranhos', c:'eu', lat:39.803, lon:-8.098, base:6, prep:60, cook:120, diff:3, tags:['lamb','rice','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#c9a878','#8f5a3a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Maranhos',en:'Maranhos'},
  p:{fr:'Sertã, Beira Baixa, Portugal',en:'Sertã, Beira Baixa, Portugal'},
  d:{fr:"L'estomac de chevreau rempli de riz, de menthe et de viandes, cousu puis mijoté. Une préparation de Pâques dans la serra portugaise, où l'on ne tuait la bête qu'une fois l'an et où rien n'était perdu.",
     en:"A kid's stomach filled with rice, mint and meats, sewn up and simmered. An Easter preparation in the Portuguese serra, where the animal was killed once a year and nothing was wasted."},
  i:[['goat_stomach',2,'pc'],['goat_meat',500,'g'],['smoked_bacon',200,'g'],['chorizo',150,'g'],['long_grain_rice',400,'g'],['mint',1,'bunch'],['onion',2,'pc'],['garlic',5,'clove'],['white_wine',250,'ml'],['lemon',2,'pc'],['piri_piri',1,'tsp'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Nettoyez longuement les estomacs au sel, au citron et à l'eau vinaigrée, puis découpez-les en poches de 15 cm.","Taillez toutes les viandes en petits dés et mêlez-les au riz cru, à l'oignon, à l'ail, à la menthe hachée et au vin blanc.","Remplissez les poches à moitié seulement — le riz double de volume — et cousez-les soigneusement au fil de cuisine.","Pochez-les 1 h 45 dans un bouillon frémissant avec le laurier, sans jamais bouillir, en les piquant deux fois.","Laissez tiédir avant de trancher : chauds, les maranhos se défont. Servez avec un filet de citron."],
     en:["Clean the stomachs thoroughly with salt, lemon and vinegared water, then cut them into 15 cm pouches.","Dice all the meats small and mix them with the raw rice, onion, garlic, chopped mint and white wine.","Fill the pouches only half full — the rice doubles — and sew them carefully with kitchen thread.","Poach for 1¾ hours in a barely simmering broth with the bay, never boiling, pricking them twice.","Let them cool before slicing: hot, maranhos fall apart. Serve with a squeeze of lemon."]} },

{ id:'bolo-levedo', c:'eu', lat:37.821, lon:-25.516, base:8, prep:120, cook:15, diff:2, tags:['bread','breakfast','sweet'],
  art:{v:'board',bg:'#33291f',plate:'#f2e6c8',style:'flat',food:['#f2dfa8','#e0b45a','#f4f0e6','#c98a2c'],garnish:'#7fae6a'},
  n:{fr:'Bolo lêvedo',en:'Bolo lêvedo'},
  p:{fr:'Ribeira Grande, São Miguel, Açores',en:'Ribeira Grande, São Miguel, Azores'},
  d:{fr:"Un pain plat et sucré cuit à la plaque, entre la brioche et le muffin anglais, né dans les fours de Furnas. On le mange tiède au petit-déjeuner, simplement beurré, ou fendu en deux et garni.",
     en:"A flat sweet bread cooked on a griddle, halfway between brioche and English muffin, born in the ovens of Furnas. Eaten warm at breakfast, simply buttered, or split and filled."},
  i:[['flour',600,'g'],['whole_milk',250,'ml'],['sugar',120,'g'],['fresh_yeast',25,'g'],['butter',80,'g'],['egg',1,'pc'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède avec une cuillerée de sucre et laissez mousser 15 minutes.","Pétrissez avec la farine, le reste du sucre, l'œuf, le beurre mou et le sel pendant 12 minutes.","Laissez lever 1 h 30, jusqu'à ce que la pâte double.","Divisez en huit boules, aplatissez-les en disques de 12 cm et 1,5 cm d'épaisseur, et laissez pousser 40 minutes sous un linge.","Cuisez sur une plaque sèche à feu doux, 7 minutes par face : ils doivent brunir sans brûler et rester moelleux au centre."],
     en:["Dissolve the yeast in the warm milk with a spoonful of sugar and let it froth for 15 minutes.","Knead with the flour, remaining sugar, egg, soft butter and salt for 12 minutes.","Prove for 1½ hours, until the dough doubles.","Divide into eight balls, flatten them into 12 cm discs 1.5 cm thick, and prove for 40 minutes under a cloth.","Cook on a dry griddle over low heat, 7 minutes a side: they should brown without burning and stay soft in the middle."]} },

{ id:'pudim-abade-de-priscos', c:'eu', lat:41.550, lon:-8.428, base:8, prep:30, cook:90, diff:3, tags:['sweet','festive','pork'],
  art:{v:'plate',bg:'#2e2419',plate:'#f4ead4',style:'cake',food:['#8f6a4a','#6f4a2a','#f0e0bc','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Pudding de l’abbé de Priscos',en:'Abade de Priscos pudding'},
  p:{fr:'Braga, Minho, Portugal',en:'Braga, Minho, Portugal'},
  d:{fr:"Un flan de quinze jaunes d'œufs, de porto et — c'est là son secret — de lard de porc, qui lui donne une onctuosité sans pareille. Le père Manuel Rebelo, curé gourmand de Priscos, ne livra jamais sa recette de son vivant.",
     en:"A custard of fifteen egg yolks, port and — this is its secret — pork fat, which gives it an unmatched silkiness. Father Manuel Rebelo, the greedy priest of Priscos, never gave up the recipe in his lifetime."},
  i:[['egg_yolk',15,'pc'],['sugar',500,'g'],['water',300,'ml'],['pork_fat',60,'g'],['port_wine',80,'ml'],['lemon_zest',2,'pc'],['cinnamon',1,'pc'],['salt',null,'']],
  s:{fr:["Faites un caramel blond avec 150 g de sucre et un peu d'eau, versez-le dans un moule à cheminée et faites-le tourner pour tapisser les parois.","Cuisez le reste du sucre avec l'eau, le zeste, la cannelle et le lard en un sirop, 10 minutes à petits bouillons.","Retirez le lard, laissez tiédir le sirop et filtrez-le.","Battez les jaunes sans les faire mousser — les bulles gâteraient la texture — puis versez le sirop tiède en filet, et enfin le porto.","Passez au chinois, versez dans le moule et cuisez au bain-marie 1 h 15 à 180 °C. Laissez refroidir une nuit avant de démouler."],
     en:["Make a pale caramel with 150 g of sugar and a little water, pour it into a ring mould and swirl to coat the sides.","Cook the remaining sugar with the water, zest, cinnamon and pork fat into a syrup, 10 minutes at a gentle boil.","Lift out the fat, let the syrup cool a little and strain it.","Beat the yolks without frothing them — bubbles would spoil the texture — then pour in the warm syrup in a thread, and finally the port.","Pass through a sieve, pour into the mould and bake in a bain-marie for 1¼ hours at 180°C. Cool overnight before turning out."]} },

{ id:'garbure', c:'eu', lat:43.296, lon:-0.370, base:6, prep:30, cook:150, diff:1, tags:['soup','pork','slow'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'soup',food:['#4f6f3a','#e8dcb8','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Garbure béarnaise',en:'Béarn garbure'},
  p:{fr:'Pau, Béarn, France',en:'Pau, Béarn, France'},
  d:{fr:"Une soupe de chou et de haricots où l'on plonge un manche de confit de canard. Le test béarnais est connu : la cuillère plantée au milieu doit tenir debout toute seule, sinon ce n'est qu'un potage.",
     en:"A cabbage and bean soup into which a leg of duck confit is plunged. The Béarn test is well known: a spoon stood in the middle must stay upright on its own, or it is merely soup."},
  i:[['duck_confit',4,'pc'],['cabbage',1,'pc'],['white_beans',300,'g'],['potato',600,'g'],['carrot',3,'pc'],['turnip',3,'pc'],['leek',2,'pc'],['smoked_pork_collar',400,'g'],['garlic',6,'clove'],['thyme',3,'sprig'],['bay_leaf',2,'pc'],['duck_fat',60,'g'],['rustic_bread',8,'slice'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les haricots la veille, puis mettez-les à cuire dans trois litres d'eau avec le collier fumé, une heure.","Ajoutez carottes, navets et poireaux en gros morceaux, ainsi que l'ail, le thym et le laurier.","Trente minutes plus tard, incorporez les pommes de terre et le chou effeuillé et grossièrement haché.","Faites réchauffer les cuisses de confit dans leur graisse et posez-les dans la soupe pour les vingt dernières minutes.","Servez très épais, sur des tranches de pain rassis. Finissez à la béarnaise : un verre de vin rouge versé dans le fond de l'assiette."],
     en:["Soak the beans overnight, then cook them in three litres of water with the smoked collar for an hour.","Add carrots, turnips and leeks in large pieces, along with the garlic, thyme and bay.","Thirty minutes later, add the potatoes and the cabbage, leaves separated and roughly chopped.","Warm the confit legs in their fat and lay them in the soup for the last twenty minutes.","Serve very thick, over slices of stale bread. Finish in the Béarn manner: a glass of red wine poured into the bottom of the plate."]} },

{ id:'poule-au-pot', c:'eu', lat:43.334, lon:-0.428, base:6, prep:40, cook:180, diff:2, tags:['poultry','sunday','slow'],
  art:{v:'pot',bg:'#2c3440',plate:'#f0e4c8',style:'soup',food:['#e8dcc0','#e0b45a','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poule au pot farcie',en:'Stuffed poule au pot'},
  p:{fr:'Lescar, Béarn, France',en:'Lescar, Béarn, France'},
  d:{fr:"La poule farcie au jambon et au pain, pochée avec ses légumes. Henri IV, né à Pau, aurait souhaité que chaque laboureur puisse en mettre une au pot le dimanche — la phrase lui a peut-être été prêtée, le plat lui est resté.",
     en:"A hen stuffed with ham and bread, poached with its vegetables. Henri IV, born in Pau, is said to have wished every ploughman could put one in the pot on Sundays — the phrase may be invented, the dish stayed with him."},
  i:[['chicken',2,'kg'],['bayonne_ham',200,'g'],['stale_bread',200,'g'],['whole_milk',200,'ml'],['egg',2,'pc'],['garlic',5,'clove'],['parsley',1,'bunch'],['carrot',4,'pc'],['leek',3,'pc'],['turnip',3,'pc'],['celery',3,'stalk'],['onion',2,'pc'],['cloves',3,'pc'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Préparez la farce : pain trempé dans le lait et pressé, jambon haché, foie de la volaille, ail, persil et œufs.","Farcissez la poule sans tasser — la farce gonfle — et cousez l'ouverture ; bridez-la solidement.","Portez trois litres d'eau à frémissement, plongez la poule et écumez patiemment pendant vingt minutes.","Ajoutez l'oignon piqué de clous, le laurier et le sel, et laissez pocher 2 heures sans jamais bouillir.","Ajoutez les légumes en gros morceaux pour les 40 dernières minutes. Servez le bouillon d'abord, puis la poule, la farce et les légumes."],
     en:["Make the stuffing: bread soaked in milk and squeezed, chopped ham, the bird's liver, garlic, parsley and eggs.","Stuff the hen without packing it — the stuffing swells — and sew the opening; truss it firmly.","Bring three litres of water to a simmer, lower in the hen and skim patiently for twenty minutes.","Add the clove-studded onion, bay and salt, and poach for 2 hours without ever boiling.","Add the vegetables in large pieces for the last 40 minutes. Serve the broth first, then the hen, stuffing and vegetables."]} },

{ id:'coq-au-vin', c:'eu', lat:47.024, lon:4.840, base:6, prep:40, cook:150, diff:2, tags:['poultry','slow','sunday'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f2a2a','#8f5a3a','#c9a878','#e8d8b8'],garnish:'#7fae6a'},
  n:{fr:'Coq au vin',en:'Coq au vin'},
  p:{fr:'Beaune, Bourgogne, France',en:'Beaune, Burgundy, France'},
  d:{fr:"Un coq — un vrai, ferme et âgé — mariné puis braisé une nuit entière dans le vin rouge. La sauce se lie au sang de la bête ou, à défaut, au foie mixé : c'est ce qui la distingue d'un simple bourguignon de volaille.",
     en:"A cockerel — a real one, firm and old — marinated then braised overnight in red wine. The sauce is bound with the bird's blood or, failing that, its blended liver: that is what sets it apart from a mere chicken bourguignon."},
  i:[['chicken',2.5,'kg'],['red_wine',1,'l'],['smoked_bacon',200,'g'],['pearl_onions',300,'g'],['button_mushrooms',400,'g'],['carrot',3,'pc'],['garlic',6,'clove'],['brandy',80,'ml'],['flour',3,'tbsp'],['butter',80,'g'],['thyme',4,'sprig'],['bay_leaf',3,'pc'],['parsley',5,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Découpez le coq en huit et laissez-le mariner 24 heures dans le vin rouge avec carotte, ail, thym et laurier.","Égouttez et épongez soigneusement les morceaux : mouillés, ils ne coloreraient pas.","Saisissez-les au beurre, flambez au marc, singez à la farine et laissez cuire deux minutes.","Versez la marinade filtrée et portée à ébullition, et laissez mijoter 2 heures à couvert, à feu très doux.","Faites glacer les oignons grelots et sauter les champignons à part, ajoutez-les en fin de cuisson avec les lardons rissolés."],
     en:["Joint the cockerel into eight and marinate for 24 hours in the red wine with carrot, garlic, thyme and bay.","Drain and dry the pieces thoroughly: wet, they would not colour.","Sear them in butter, flame with marc, dust with flour and cook for two minutes.","Pour in the strained marinade, brought to the boil beforehand, and simmer covered for 2 hours over very low heat.","Glaze the button onions and fry the mushrooms separately, adding them at the end with the browned lardons."]} },

{ id:'gratin-dauphinois', c:'eu', lat:45.188, lon:5.724, base:6, prep:20, cook:90, diff:1, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'stew',food:['#f0e8d0','#e0b45a','#f4f0e6','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Gratin dauphinois',en:'Gratin dauphinois'},
  p:{fr:'Grenoble, Dauphiné, France',en:'Grenoble, Dauphiné, France'},
  d:{fr:"Des pommes de terre en lamelles cuites dans le lait et la crème, à l'ail, et rien d'autre. Ni fromage, ni œuf : la recette attestée en 1788 par le lieutenant général du Dauphiné n'en mentionne aucun des deux.",
     en:"Sliced potatoes cooked in milk and cream with garlic, and nothing else. No cheese, no egg: the recipe recorded in 1788 by the lieutenant general of Dauphiné mentions neither."},
  i:[['potato',1.5,'kg'],['whole_milk',500,'ml'],['heavy_cream',400,'ml'],['garlic',3,'clove'],['butter',40,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Choisissez des pommes de terre à chair ferme et taillez-les en rondelles de 3 mm, sans jamais les rincer : l'amidon fait la liaison.","Frottez le plat d'une gousse d'ail coupée, puis beurrez-le généreusement.","Faites chauffer le lait avec l'ail restant écrasé, la muscade, le sel et le poivre, et versez-y les pommes de terre. Laissez frémir 10 minutes en remuant doucement.","Transvasez dans le plat en tassant les couches, puis versez la crème par-dessus.","Enfournez 1 h 15 à 150 °C. La lame d'un couteau doit traverser sans résistance et le dessus être doré, non gratiné."],
     en:["Choose firm-fleshed potatoes and cut them into 3 mm rounds, never rinsing them: the starch makes the binding.","Rub the dish with a cut garlic clove, then butter it generously.","Heat the milk with the remaining crushed garlic, nutmeg, salt and pepper, and add the potatoes. Simmer for 10 minutes, stirring gently.","Transfer to the dish, pressing the layers down, then pour the cream over.","Bake for 1¼ hours at 150°C. A knife blade should pass through without resistance and the top be golden, not crusted."]} },

{ id:'socca', c:'eu', lat:43.581, lon:7.125, base:6, prep:15, cook:10, diff:1, tags:['veg','street','fast'],
  art:{v:'board',bg:'#33301f',plate:'#f0e2c0',style:'flat',food:['#e8c87a','#c9a24a','#f2dfa8','#8f6a2b'],garnish:'#7fae6a'},
  n:{fr:'Socca',en:'Socca'},
  p:{fr:'Antibes, Côte d’Azur, France',en:'Antibes, French Riviera, France'},
  d:{fr:"Une galette de pois chiches cuite dans un four à bois sur une plaque de cuivre, servie brûlante, poivrée et déchirée à la main. Cousine de la farinata génoise, elle se vend au poids sur les marchés du littoral.",
     en:"A chickpea pancake baked in a wood oven on a copper tray, served scalding, peppered and torn by hand. Cousin to Genoese farinata, sold by weight in the markets of the coast."},
  i:[['chickpea_flour',250,'g'],['water',750,'ml'],['olive_oil',60,'ml'],['salt',8,'g'],['pepper',null,'']],
  s:{fr:["Fouettez la farine de pois chiches dans l'eau tiède, sans le moindre grumeau, et salez.","Laissez reposer une heure au moins, en écumant la mousse qui remonte à la surface.","Incorporez l'huile d'olive : la pâte doit rester très liquide, comme une crêpe.","Chauffez une plaque huilée au maximum de votre four, sous le gril, puis versez une couche de 3 mm à peine.","Enfournez 8 minutes tout en haut : le dessus doit brûler par endroits. Poivrez généreusement, déchirez à la main et mangez debout."],
     en:["Whisk the chickpea flour into warm water without a single lump, and salt it.","Rest for at least an hour, skimming the foam that rises.","Stir in the olive oil: the batter should stay very liquid, like a crêpe batter.","Heat an oiled tray in the hottest part of your oven, under the grill, then pour in a layer barely 3 mm deep.","Bake for 8 minutes at the very top: the surface should scorch in places. Pepper generously, tear by hand and eat standing up."]} },

{ id:'daube-provencale', c:'eu', lat:43.529, lon:5.447, base:6, prep:40, cook:240, diff:2, tags:['beef','slow','sunday'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f2a2a','#8f5a3a','#c9a878','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Daube provençale',en:'Provençal daube'},
  p:{fr:'Aix-en-Provence, Provence, France',en:'Aix-en-Provence, Provence, France'},
  d:{fr:"Du bœuf mariné au vin et à l'orange, mijoté quatre heures dans une daubière au col étroit qui retient la vapeur. On y ajoute des olives noires et un zeste d'orange séché : c'est ce qui la sépare du bourguignon.",
     en:"Beef marinated in wine and orange, stewed for four hours in a narrow-necked daubière that traps the steam. Black olives and a dried orange peel go in: that is what separates it from a bourguignon."},
  i:[['beef_chuck',1.5,'kg'],['red_wine',750,'ml'],['orange_zest',2,'pc'],['carrot',4,'pc'],['onion',3,'pc'],['garlic',8,'clove'],['black_olives',150,'g'],['smoked_bacon',200,'g'],['ripe_tomato',300,'g'],['thyme',4,'sprig'],['bay_leaf',3,'pc'],['cloves',4,'pc'],['olive_oil',80,'ml'],['pasta',400,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner le bœuf en gros cubes 24 heures dans le vin rouge avec carotte, oignon, ail, thym, laurier et zeste d'orange.","Égouttez et épongez la viande, saisissez-la dans l'huile très chaude par petites quantités.","Faites revenir les lardons et les légumes de la marinade dans la même cocotte.","Remettez tout, versez la marinade portée à ébullition et la tomate, et laissez mijoter 4 heures à feu très doux, à couvert.","Ajoutez les olives dénoyautées la dernière demi-heure. Servez avec des macaronis, comme à Nice, ou laissez refroidir pour le lendemain."],
     en:["Marinate the beef in large cubes for 24 hours in red wine with carrot, onion, garlic, thyme, bay and orange peel.","Drain and dry the meat, then sear it in very hot oil in small batches.","Fry the lardons and the marinade vegetables in the same pot.","Return everything, pour in the marinade brought to the boil and the tomato, and simmer for 4 hours over very low heat, covered.","Add the stoned olives for the last half hour. Serve with macaroni, as they do in Nice, or cool it for the next day."]} },

{ id:'tielle-setoise', c:'eu', lat:43.404, lon:3.694, base:6, prep:60, cook:35, diff:2, tags:['sea','bake','street'],
  art:{v:'board',bg:'#33251c',plate:'#f2e6c8',style:'pastry',food:['#c9402c','#e0b45a','#8f3b2a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Tielle sétoise',en:'Tielle from Sète'},
  p:{fr:'Sète, Languedoc, France',en:'Sète, Languedoc, France'},
  d:{fr:"Une tourte au poulpe et à la sauce tomate pimentée, apportée par les pêcheurs de Gaeta installés à Sète au XIXe siècle. Longtemps préparée à la maison seulement, elle ne fut vendue qu'à partir de 1937.",
     en:"An octopus pie in a spiced tomato sauce, brought by fishermen from Gaeta who settled in Sète in the 19th century. Made only at home for decades, it was not sold until 1937."},
  i:[['octopus',1,'kg'],['flour',500,'g'],['olive_oil',120,'ml'],['warm_water',200,'ml'],['dry_yeast',7,'g'],['ripe_tomato',600,'g'],['onion',2,'pc'],['garlic',5,'clove'],['white_wine',150,'ml'],['piri_piri',2,'tsp'],['sweet_paprika',1,'tbsp'],['parsley',4,'tbsp'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites cuire le poulpe 45 minutes à petits bouillons avec le laurier, puis laissez-le refroidir dans son eau et coupez-le en petits dés.","Pétrissez la farine, l'eau tiède, la levure, l'huile et le sel, et laissez lever une heure.","Faites une sauce en réduisant tomate, oignon, ail, vin blanc, paprika et piment 30 minutes, jusqu'à ce qu'elle soit très épaisse.","Mêlez le poulpe à la sauce et laissez refroidir : chaude, la garniture détremperait la pâte.","Foncez de petits moules, garnissez, couvrez d'un disque de pâte, soudez en pinçant le bord et enfournez 30 minutes à 200 °C. Se mangent tièdes."],
     en:["Cook the octopus for 45 minutes at a gentle boil with the bay, then let it cool in its water and dice it small.","Knead the flour, warm water, yeast, oil and salt, and prove for an hour.","Make a sauce by reducing tomato, onion, garlic, white wine, paprika and chilli for 30 minutes, until very thick.","Mix the octopus into the sauce and let it cool: hot, the filling would sog the pastry.","Line small tins, fill them, cover with a disc of dough, seal by crimping the edge and bake for 30 minutes at 200°C. Eaten warm."]} },

{ id:'cargolade', c:'eu', lat:42.699, lon:2.895, base:6, prep:120, cook:30, diff:2, tags:['grill','festive','street'],
  art:{v:'board',bg:'#2b2a1c',plate:'#e8d8b8',style:'grill',food:['#c9a878','#8f6a4a','#e0b45a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Cargolade',en:'Cargolade'},
  p:{fr:'Perpignan, Roussillon, France',en:'Perpignan, Roussillon, France'},
  d:{fr:"Des escargots grillés sur un feu de sarments, ouverture vers le haut, arrosés de lard fondu goutte à goutte. C'est moins un plat qu'un rassemblement : on y passe l'après-midi, à l'aïoli et au vin de la vallée.",
     en:"Snails grilled over a vine-shoot fire, opening upwards, basted drop by drop with melting bacon fat. Less a dish than a gathering: an afternoon spent over aioli and valley wine."},
  i:[['snails',60,'pc'],['smoked_bacon',400,'g'],['pork_sausage',6,'pc'],['garlic',10,'clove'],['egg_yolk',2,'pc'],['olive_oil',300,'ml'],['coarse_salt',3,'tbsp'],['piri_piri',1,'tsp'],['rustic_bread',1,'pc'],['pepper',null,'']],
  s:{fr:["Faites jeûner les escargots une semaine, puis lavez-les longuement à l'eau vinaigrée jusqu'à ce que l'eau reste claire.","Disposez-les ouverture vers le haut sur une grille, serrés les uns contre les autres, et salez chaque ouverture.","Allumez un feu de sarments et laissez-le tomber en braises : la flamme vive les ferait éclater.","Faites griller 15 minutes, puis posez les tranches de lard sur une grille au-dessus : la graisse fondue tombe dans les coquilles.","Montez un aïoli au mortier avec l'ail, les jaunes, le sel et l'huile en filet. Mangez les escargots à la main, trempés dedans."],
     en:["Starve the snails for a week, then wash them at length in vinegared water until it runs clear.","Set them opening upwards on a grill, packed tightly together, and salt each opening.","Light a fire of vine shoots and let it fall to embers: an open flame would make them burst.","Grill for 15 minutes, then lay the bacon slices on a rack above: the melting fat drips into the shells.","Mount an aioli in a mortar with the garlic, yolks, salt and oil in a thread. Eat the snails by hand, dipped in it."]} },

{ id:'mouclade-charentaise', c:'eu', lat:46.160, lon:-1.152, base:4, prep:25, cook:20, diff:1, tags:['sea','fast','sunday'],
  art:{v:'pot',bg:'#26404c',plate:'#f4ecd8',style:'fish',food:['#f0e0a8','#3a3a4a','#f4f0e6','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Mouclade charentaise',en:'Mouclade charentaise'},
  p:{fr:'La Rochelle, Aunis, France',en:'La Rochelle, Aunis, France'},
  d:{fr:"Des moules de bouchot dans une crème au curry et au pineau des Charentes. Le curry surprend : il est arrivé au XVIIe siècle par le port de La Rochelle, avec les navires de la Compagnie des Indes.",
     en:"Bouchot mussels in a cream sauce with curry and Pineau des Charentes. The curry surprises: it arrived in the 17th century through the port of La Rochelle, on East India Company ships."},
  i:[['mussels',2,'kg'],['shallot',3,'pc'],['garlic',3,'clove'],['white_wine',250,'ml'],['heavy_cream',300,'ml'],['egg_yolk',2,'pc'],['butter',60,'g'],['flour',2,'tbsp'],['curry_powder',2,'tsp'],['parsley',4,'tbsp'],['bay_leaf',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Grattez et ébarbez les moules, jetez celles qui restent ouvertes après un choc sur le plan de travail.","Faites-les ouvrir 4 minutes à feu vif avec les échalotes, le vin blanc et le laurier, puis retirez-les.","Filtrez le jus à travers un linge fin : il reste toujours un peu de sable au fond.","Faites un roux blond avec le beurre et la farine, ajoutez le curry, mouillez du jus filtré et laissez cuire 5 minutes.","Liez avec les jaunes battus dans la crème, hors du feu. Retirez une coquille sur deux, nappez les moules et parsemez de persil."],
     en:["Scrape and beard the mussels, discarding any that stay open after a tap on the worktop.","Open them over high heat for 4 minutes with the shallots, white wine and bay, then lift them out.","Strain the liquor through a fine cloth: there is always a little sand at the bottom.","Make a pale roux with the butter and flour, add the curry, whisk in the strained liquor and cook for 5 minutes.","Bind with the yolks beaten into the cream, off the heat. Remove one shell from each mussel, coat them and scatter parsley."]} },

{ id:'lamproie-a-la-bordelaise', c:'eu', lat:44.914, lon:-0.244, base:6, prep:60, cook:120, diff:3, tags:['sea','slow','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'fish',food:['#6f2a2a','#8f3b2a','#4f6f3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Lamproie à la bordelaise',en:'Lamprey à la bordelaise'},
  p:{fr:'Libourne, Gironde, France',en:'Libourne, Gironde, France'},
  d:{fr:"La lamproie de Garonne mijotée dans le vin rouge avec du poireau, liée à son propre sang. Un plat de printemps, de plus en plus rare : le poisson est aujourd'hui protégé et la pêche strictement encadrée.",
     en:"Garonne lamprey stewed in red wine with leek and bound with its own blood. A spring dish, increasingly rare: the fish is now protected and the fishery closely regulated."},
  i:[['lamprey',1.5,'kg'],['red_wine',1,'l'],['leek',8,'pc'],['bayonne_ham',150,'g'],['onion',2,'pc'],['garlic',6,'clove'],['brandy',60,'ml'],['flour',3,'tbsp'],['butter',80,'g'],['bay_leaf',3,'pc'],['thyme',3,'sprig'],['rustic_bread',8,'slice'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Ébouillantez la lamproie pour retirer le mucus, saignez-la en gardant le sang dans un bol avec un verre de vin.","Retirez le nerf dorsal en tirant sur la corde blanche près de la tête : sans cela, le plat serait amer.","Tronçonnez et faites revenir avec l'oignon, l'ail et le jambon dans le beurre, flambez au marc.","Ajoutez les blancs de poireaux en tronçons, singez, versez le vin rouge et laissez mijoter 1 h 30 à feu doux.","Liez au sang hors du feu, sans plus jamais bouillir. Servez sur des croûtons frottés à l'ail — meilleur réchauffé le lendemain."],
     en:["Scald the lamprey to remove the mucus, bleed it and keep the blood in a bowl with a glass of wine.","Pull out the dorsal nerve by tugging the white cord near the head: without this, the dish would be bitter.","Cut into sections and fry with the onion, garlic and ham in butter, then flame with marc.","Add the white of the leeks in lengths, dust with flour, pour in the red wine and simmer for 1½ hours over low heat.","Bind with the blood off the heat, never boiling again. Serve on garlic-rubbed croutons — better still reheated the next day."]} },

{ id:'mique-du-perigord', c:'eu', lat:45.184, lon:0.721, base:6, prep:40, cook:120, diff:2, tags:['comfort','pork','slow'],
  art:{v:'pot',bg:'#2f3328',plate:'#f0e4c8',style:'stew',food:['#f0e8d0','#8f5a3a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mique du Périgord',en:'Périgord mique'},
  p:{fr:'Périgueux, Périgord, France',en:'Périgueux, Périgord, France'},
  d:{fr:"Une grosse boule de pain levée, pochée dans le bouillon d'une potée au petit salé. Elle gonfle en cuisant et se tranche à table ; c'était le pain du pauvre, cuit sans four dans la marmite.",
     en:"A large ball of leavened bread poached in the broth of a salt-pork stew. It swells as it cooks and is sliced at the table; the poor man's bread, baked without an oven, in the pot."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['egg',3,'pc'],['whole_milk',150,'ml'],['duck_fat',80,'g'],['salted_pork',800,'g'],['cabbage',1,'pc'],['carrot',4,'pc'],['turnip',3,'pc'],['leek',3,'pc'],['onion',2,'pc'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites dessaler le petit salé 12 heures, puis mettez-le à cuire dans trois litres d'eau avec le laurier, une heure.","Pétrissez la farine, la levure délayée dans le lait tiède, les œufs, la graisse de canard et le sel ; laissez lever 2 heures.","Ajoutez les légumes en gros morceaux au bouillon.","Formez une grosse boule avec la pâte, sans la retravailler, et déposez-la délicatement sur le bouillon frémissant.","Couvrez et laissez pocher 45 minutes en la retournant à mi-cuisson : elle double de volume. Tranchez-la à table, avec la potée."],
     en:["Desalt the pork for 12 hours, then cook it in three litres of water with the bay for an hour.","Knead the flour, the yeast dissolved in warm milk, the eggs, duck fat and salt; prove for 2 hours.","Add the vegetables in large pieces to the broth.","Shape the dough into a large ball without reworking it, and lower it gently onto the simmering broth.","Cover and poach for 45 minutes, turning it halfway: it doubles in size. Slice it at the table, with the stew."]} },

{ id:'tourin-a-l-ail', c:'eu', lat:44.203, lon:0.616, base:4, prep:15, cook:30, diff:1, tags:['soup','veg','fast'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#e8dcc0','#f4f0e6','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Tourin à l’ail',en:'Garlic tourin'},
  p:{fr:'Agen, Lot-et-Garonne, France',en:'Agen, Lot-et-Garonne, France'},
  d:{fr:"Une soupe à l'ail liée au blanc d'œuf en filaments et au jaune monté au vinaigre. On l'apportait aux mariés au milieu de la nuit de noces, dans une soupière, avec une insistance dont on devine le motif.",
     en:"A garlic soup threaded with egg white and finished with a yolk beaten with vinegar. It was brought to newlyweds in the middle of their wedding night, in a tureen, with an insistence whose motive one can guess."},
  i:[['garlic',2,'pc'],['duck_fat',60,'g'],['flour',2,'tbsp'],['water',1.5,'l'],['egg',3,'pc'],['white_wine_vinegar',3,'tbsp'],['stale_bread',8,'slice'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Épluchez deux têtes d'ail entières, retirez le germe et écrasez les gousses du plat du couteau.","Faites-les fondre très doucement dans la graisse de canard 10 minutes, sans jamais les colorer : l'ail brûlé rendrait la soupe amère.","Singez à la farine, mouillez de l'eau bouillante et laissez frémir 20 minutes.","Versez les blancs battus en filet dans le bouillon frémissant, en remuant : ils forment des filaments.","Hors du feu, liez avec les jaunes battus au vinaigre. Servez sur du pain rassis, avec du persil."],
     en:["Peel two whole heads of garlic, remove the green germ and crush the cloves with the flat of a knife.","Soften them very gently in the duck fat for 10 minutes, never letting them colour: burnt garlic would make the soup bitter.","Dust with flour, pour in the boiling water and simmer for 20 minutes.","Trickle the beaten whites into the simmering broth, stirring: they set into threads.","Off the heat, bind with the yolks beaten with vinegar. Serve over stale bread, with parsley."]} },

{ id:'estofinado', c:'eu', lat:44.352, lon:2.037, base:6, prep:40, cook:60, diff:2, tags:['sea','comfort','slow'],
  art:{v:'pot',bg:'#33301f',plate:'#f4ecd8',style:'stew',food:['#f0e8d0','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Estofinado',en:'Estofinado'},
  p:{fr:'Villefranche-de-Rouergue, Rouergue, France',en:'Villefranche-de-Rouergue, Rouergue, France'},
  d:{fr:"De la morue séchée réhydratée, écrasée avec des pommes de terre, de l'ail et de l'huile de noix. Le stockfisch norvégien remontait le Lot par gabares jusqu'à Decazeville : voilà pourquoi ce plat de mer se mange à trois cents kilomètres des côtes.",
     en:"Dried cod rehydrated and crushed with potatoes, garlic and walnut oil. Norwegian stockfish came up the Lot by barge as far as Decazeville: which is why this sea dish is eaten three hundred kilometres inland."},
  i:[['stockfish',600,'g'],['potato',1,'kg'],['garlic',8,'clove'],['egg',4,'pc'],['walnuts',60,'g'],['heavy_cream',200,'ml'],['parsley',1,'bunch'],['olive_oil',150,'ml'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper le stockfisch quatre jours à l'eau froide courante ou en changeant l'eau matin et soir.","Pochez-le 20 minutes sans bouillir, puis effeuillez-le en éliminant peau et arêtes avec patience.","Faites cuire les pommes de terre à l'eau salée et écrasez-les au presse-purée, encore chaudes.","Mêlez le poisson, les pommes de terre, l'ail écrasé, les œufs durs hachés et les noix pilées.","Incorporez l'huile de noix et la crème en travaillant à la cuillère de bois sur feu très doux, jusqu'à obtenir une masse onctueuse. Citronnez et couvrez de persil."],
     en:["Soak the stockfish for four days in cold running water, or changing the water morning and evening.","Poach it for 20 minutes without boiling, then flake it patiently, removing skin and bones.","Boil the potatoes in salted water and rice them while still hot.","Combine the fish, potatoes, crushed garlic, chopped hard-boiled eggs and pounded walnuts.","Work in the walnut oil and cream with a wooden spoon over very low heat, until the mass turns silky. Sharpen with lemon and cover with parsley."]} },

{ id:'truffade', c:'eu', lat:44.926, lon:2.443, base:4, prep:20, cook:35, diff:1, tags:['cheese','comfort','veg'],
  art:{v:'pot',bg:'#33301f',plate:'#f0e2c0',style:'flat',food:['#e0b45a','#f0e0a8','#c98a2c','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Truffade',en:'Truffade'},
  p:{fr:'Aurillac, Cantal, France',en:'Aurillac, Cantal, France'},
  d:{fr:"Des pommes de terre rissolées écrasées avec de la tomme fraîche du Cantal, jusqu'à ce que le fromage file en longs rubans. Ce n'est pas l'aligot : ici les pommes de terre restent en morceaux, et il n'y a pas de crème.",
     en:"Fried potatoes crushed with fresh Cantal tomme until the cheese pulls into long ribbons. This is not aligot: here the potatoes stay in pieces, and there is no cream."},
  i:[['potato',1,'kg'],['tomme_fraiche',400,'g'],['smoked_bacon',200,'g'],['garlic',3,'clove'],['duck_fat',80,'g'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez les pommes de terre en lamelles de 5 mm et faites-les rissoler dans la graisse de canard 20 minutes, à couvert puis à découvert.","Ajoutez les lardons et l'ail écrasé, laissez colorer l'ensemble.","Écrasez grossièrement à la spatule, en gardant des morceaux entiers : la truffade n'est pas une purée.","Coupez la tomme fraîche en fines lamelles et incorporez-la hors du feu, en soulevant la masse.","Remettez sur feu doux et travaillez à la spatule jusqu'à ce que le fromage file. Servez aussitôt, dans la poêle."],
     en:["Cut the potatoes into 5 mm slices and fry them in duck fat for 20 minutes, covered then uncovered.","Add the lardons and crushed garlic, and let everything colour.","Crush roughly with a spatula, keeping whole pieces: truffade is not a purée.","Slice the fresh tomme thinly and fold it in off the heat, lifting the mass.","Return to low heat and work with the spatula until the cheese pulls into threads. Serve at once, in the pan."]} },

{ id:'rillettes-du-mans', c:'eu', lat:48.007, lon:0.199, base:8, prep:30, cook:300, diff:2, tags:['pork','slow','comfort'],
  art:{v:'bowl',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#c9a878','#8f6a4a','#e8d8b8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Rillettes du Mans',en:'Rillettes du Mans'},
  p:{fr:'Le Mans, Maine, France',en:'Le Mans, Maine, France'},
  d:{fr:"Du porc cuit cinq heures dans sa graisse puis effiloché à la fourchette, sans jamais être broyé. Celles du Mans sont brunes et fibreuses, contrairement aux rillettes de Tours, plus pâles et plus grasses.",
     en:"Pork cooked for five hours in its own fat then pulled apart with forks, never ground. Those of Le Mans are brown and fibrous, unlike the rillettes of Tours, paler and fattier."},
  i:[['pork_shoulder',1.5,'kg'],['pork_belly',700,'g'],['pork_fat',400,'g'],['white_wine',250,'ml'],['garlic',6,'clove'],['thyme',4,'sprig'],['bay_leaf',3,'pc'],['cloves',3,'pc'],['coarse_salt',30,'g'],['rustic_bread',1,'pc'],['pepper',null,'']],
  s:{fr:["Taillez les viandes en gros lardons de 5 cm et salez-les la veille avec le poivre et les aromates.","Faites fondre le gras au fond d'une cocotte en fonte, puis ajoutez les viandes sans les colorer.","Mouillez au vin blanc, couvrez et laissez cuire 5 heures à 120 °C, en remuant toutes les heures.","La chair doit se défaire d'elle-même : effilochez-la à deux fourchettes, dans le sens des fibres, jamais au robot.","Rectifiez le sel à froid — la graisse en masque le goût à chaud — puis mettez en pots et couvrez de graisse fondue."],
     en:["Cut the meats into large 5 cm strips and salt them the day before with the pepper and aromatics.","Melt the fat in the base of a cast-iron pot, then add the meats without colouring them.","Moisten with white wine, cover and cook for 5 hours at 120°C, stirring every hour.","The meat should fall apart on its own: shred it with two forks along the fibres, never in a machine.","Adjust the salt when cold — hot fat masks it — then pot them up and seal with melted fat."]} },

{ id:'far-breton', c:'eu', lat:47.996, lon:-4.098, base:8, prep:20, cook:50, diff:1, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#2e2419',plate:'#f4ead4',style:'cake',food:['#e8c46a','#6f2a2a','#f0e0bc','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Far breton aux pruneaux',en:'Far breton with prunes'},
  p:{fr:'Quimper, Cornouaille, France',en:'Quimper, Cornouaille, France'},
  d:{fr:"Un flan épais et dense, entre le clafoutis et le pudding, semé de pruneaux macérés. Far vient du latin far, la farine d'épeautre : c'était à l'origine une bouillie salée, servie avec le lard.",
     en:"A thick dense custard, between clafoutis and pudding, studded with steeped prunes. Far comes from the Latin far, spelt flour: it began as a savoury porridge, served with bacon."},
  i:[['flour',250,'g'],['egg',4,'pc'],['sugar',180,'g'],['whole_milk',750,'ml'],['salted_butter',80,'g'],['prunes',300,'g'],['dark_rum',80,'ml'],['vanilla',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites macérer les pruneaux dans le rhum tiède au moins deux heures, la veille de préférence.","Fouettez les œufs et le sucre, ajoutez la farine tamisée et le sel sans travailler, puis le lait tiède peu à peu.","Incorporez le beurre fondu et la vanille ; la pâte doit être aussi fluide qu'une pâte à crêpes.","Laissez reposer une heure, puis versez dans un plat beurré et répartissez les pruneaux égouttés.","Enfournez 50 minutes à 200 °C : le far gonfle puis retombe en refroidissant, c'est normal. Mangez-le tiède ou froid, jamais chaud."],
     en:["Steep the prunes in warm rum for at least two hours, ideally overnight.","Whisk the eggs and sugar, add the sifted flour and salt without working it, then the warm milk little by little.","Stir in the melted butter and vanilla; the batter should be as fluid as crêpe batter.","Rest for an hour, then pour into a buttered dish and scatter over the drained prunes.","Bake for 50 minutes at 200°C: the far rises then sinks as it cools, which is normal. Eat it warm or cold, never hot."]} },

{ id:'teurgoule', c:'eu', lat:49.418, lon:0.232, base:8, prep:10, cook:300, diff:1, tags:['sweet','slow','rice'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'rice',food:['#c9924a','#f0e0bc','#8f6a4a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Teurgoule',en:'Teurgoule'},
  p:{fr:'Honfleur, Normandie, France',en:'Honfleur, Normandy, France'},
  d:{fr:"Un riz au lait cuit cinq heures au four à pain, jusqu'à former une peau brune et épaisse. Le nom viendrait de « tord-gueule » : les enfants s'y brûlaient en voulant la manger trop tôt.",
     en:"A rice pudding baked for five hours in a bread oven, until it forms a thick brown skin. The name is said to come from 'tord-gueule', a mouth-twister: children burnt themselves trying to eat it too soon."},
  i:[['whole_milk',2,'l'],['long_grain_rice',150,'g'],['sugar',180,'g'],['cinnamon',2,'tsp'],['nutmeg',1,'pinch'],['salt',null,'']],
  s:{fr:["Mêlez le riz, le sucre, la cannelle, la muscade et une pincée de sel dans une terrine haute et étroite, en grès de préférence.","Versez le lait froid dessus et remuez une seule fois : c'est le dernier geste, on n'y touchera plus.","Enfournez à 150 °C pendant une heure, puis baissez à 130 °C.","Laissez cuire quatre heures de plus sans jamais ouvrir ni remuer : une peau brune épaisse se forme en surface.","La teurgoule est prête quand cette peau est presque noire et le riz d'un beige profond. Mangez-la tiède, avec la fallue si vous en trouvez."],
     en:["Mix the rice, sugar, cinnamon, nutmeg and a pinch of salt in a tall narrow dish, preferably stoneware.","Pour the cold milk over and stir once only: that is the last gesture, it will not be touched again.","Bake at 150°C for an hour, then lower to 130°C.","Cook for four more hours without ever opening or stirring: a thick brown skin forms on the surface.","The teurgoule is ready when that skin is almost black and the rice a deep beige. Eat it warm, with fallue brioche if you can find it."]} },

{ id:'paris-brest', c:'eu', lat:48.804, lon:2.120, base:8, prep:90, cook:40, diff:3, tags:['sweet','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#c9924a','#f4f0e6','#8f6a4a'],garnish:'#c9754a'},
  n:{fr:'Paris-Brest',en:'Paris-Brest'},
  p:{fr:'Versailles, Île-de-France, France',en:'Versailles, Île-de-France, France'},
  d:{fr:"Une couronne de pâte à choux fourrée d'une crème mousseline au praliné, dont la forme évoque la roue de bicyclette. Créée en 1910 pour la course cycliste Paris-Brest-Paris, dont elle a pris le nom.",
     en:"A ring of choux pastry filled with praline mousseline cream, its shape recalling a bicycle wheel. Created in 1910 for the Paris-Brest-Paris cycle race, from which it takes its name."},
  i:[['flour',150,'g'],['water',125,'ml'],['whole_milk',625,'ml'],['butter',350,'g'],['egg',5,'pc'],['egg_yolk',4,'pc'],['sugar',150,'g'],['cornstarch',50,'g'],['hazelnuts',200,'g'],['almonds',60,'g'],['powdered_sugar',40,'g'],['salt',null,'']],
  s:{fr:["Préparez le praliné : caramélisez 100 g de sucre, versez sur les noisettes torréfiées, laissez durcir et mixez longuement jusqu'à obtenir une pâte coulante.","Faites une pâte à choux : portez l'eau, 125 ml de lait, 100 g de beurre et le sel à ébullition, jetez la farine d'un coup, desséchez, puis incorporez les œufs un à un.","Dressez une couronne de 22 cm à la douille cannelée, doublez-la d'un second cercle et d'un troisième par-dessus, parsemez d'amandes effilées.","Enfournez 40 minutes à 180 °C sans ouvrir le four les 25 premières minutes.","Faites une crème pâtissière avec le lait restant, les jaunes, le sucre et la fécule ; refroidie, montez-la avec 250 g de beurre pommade et le praliné. Garnissez la couronne fendue en deux."],
     en:["Make the praline: caramelise 100 g of sugar, pour it over the roasted hazelnuts, let it set and blend at length into a flowing paste.","Make choux pastry: bring the water, 125 ml of milk, 100 g of butter and the salt to the boil, tip in the flour, dry it out, then beat in the eggs one at a time.","Pipe a 22 cm ring with a fluted nozzle, double it with a second circle and a third on top, and scatter flaked almonds.","Bake for 40 minutes at 180°C without opening the oven for the first 25 minutes.","Make a pastry cream with the remaining milk, yolks, sugar and cornstarch; once cold, beat it with 250 g of soft butter and the praline. Fill the ring, split in two."]} }
];
